package com.primehr.rewardsrecognition.report;
import com.primehr.integration.administrative.PermissionDataScope;
import com.primehr.rewardsrecognition.api.RrAwardDtos;
import com.primehr.rewardsrecognition.application.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
@Service @Transactional(readOnly=true)
public class RrReportServiceImpl implements RrReportService{
 private final RrNominationService nominations;private final RrEvaluationService evaluations;private final RrAwardService awards;private final RrReportRenderer renderer;private final int minimumCohort;
 public RrReportServiceImpl(RrNominationService n,RrEvaluationService e,RrAwardService a,RrReportRenderer r,@Value("${primehr.reporting.minimum-aggregate-cohort:5}")int m){if(m<2||m>100)throw new IllegalArgumentException("minimum aggregate cohort must be between 2 and 100");nominations=n;evaluations=e;awards=a;renderer=r;minimumCohort=m;}
 @Override public byte[] nomination(String agency,String id,String actor,PermissionDataScope scope){var n=nominations.nomination(agency,id,actor,scope);List<RrReportData.Row>rows=new ArrayList<>();add(rows,"Nomination","Status",n.status());add(rows,"Nomination","Nominee type",n.nomineeType());add(rows,"Nomination","Nominee",switch(n.nomineeType()){case"INDIVIDUAL"->n.individualName();case"GROUP"->n.groupName();default->n.organizationName();});add(rows,"Nomination","Nominator",n.nominatorName());add(rows,"Contribution","Narrative",n.contributionNarrative());add(rows,"Contribution","Publication-safe narrative",n.publicationNarrative());n.sources().forEach(s->add(rows,"Source evidence",s.type()+" / "+s.sourceLabel(),s.sourceFingerprint()));n.evidence().forEach(e->add(rows,"Evidence checklist",e.title(),e.filename()+" · "+e.visibility()+" · SHA-256 "+e.checksum()));return renderer.render("PRAISE Nomination Record","System-generated operational record; agency approval controls the official form.",actor,rows);}
 @Override public byte[] evaluation(String agency,String id,String actor,PermissionDataScope scope){var c=evaluations.get(agency,id,actor,scope);List<RrReportData.Row>rows=new ArrayList<>();add(rows,"Eligibility","Status",c.status());add(rows,"Eligibility","Summary",c.eligibilitySummary());c.findings().forEach(f->add(rows,"Eligibility finding",f.ruleCode()+" · "+f.ruleLabel(),f.outcome()+" · "+f.rationale()));c.assignments().forEach(a->add(rows,"Committee evaluation",a.displayName()+" · "+a.memberRole(),a.status()+" · score "+v(a.totalScore())+(a.conflictDeclared()?" · recused/conflict declared":"")));c.events().forEach(e->add(rows,"Decision record",e.type()+" · "+e.outcome(),e.reason()));return renderer.render("PRAISE Eligibility, Evaluation, and Decision Record","Restricted committee working record.",actor,rows);}
 @Override public byte[] award(String agency,String id,String actor,PermissionDataScope scope){var a=awards.get(agency,id,actor,scope);List<RrReportData.Row>rows=new ArrayList<>();add(rows,"Award","Award code",a.awardCode());add(rows,"Award","Status",a.revoked()?"REVOKED":"CONFERRED");add(rows,"Award","Nominee",a.nomineeDisplayName());add(rows,"Award","Category",a.categoryTitle());add(rows,"Citation","Certificate title",a.certificateTitle());add(rows,"Citation","Publication citation",a.publicationCitation());add(rows,"Citation","Conferment date",a.conferredOn());a.incentives().forEach(i->{add(rows,"Incentive authorization",i.type()+" · "+i.authorizationReference(),i.description()+" · "+v(i.authorizedAmount())+" "+v(i.currencyCode()));i.fulfillmentEvents().forEach(f->add(rows,"Fulfillment evidence",f.status(),f.details()+" · "+v(f.evidenceReference())));});a.hapEvents().forEach(h->add(rows,"External HAP packet",h.status(),v(h.externalReference())+" · "+h.details()));return renderer.render("PRAISE Award, Citation, and Fulfillment Record","System record only; it creates no Payroll, accounting, or appointment transaction.",actor,rows);}
 @Override public byte[] annualRegister(String agency,int year,String actor){var r=awards.annualRegister(agency,year);List<RrReportData.Row>rows=new ArrayList<>();add(rows,"Summary","Conferred awards",r.totalAwards());add(rows,"Summary","Revoked awards",r.revokedAwards());add(rows,"Summary","Monetary authorized",r.monetaryAuthorized());add(rows,"Summary","Monetary fulfilled",r.monetaryFulfilled());r.records().forEach(x->add(rows,"Annual register",x.awardCode()+" · "+x.nomineeDisplayName(),x.categoryTitle()+" · "+x.status()+" · "+x.conferredOn()));return renderer.render("Annual PRAISE Register — "+year,"Current award revisions with revocations visibly retained.",actor,rows);}
 @Override public RrReportData.Analytics analytics(String agency,int year){var r=awards.annualRegister(agency,year);int cohort=(int)r.records().stream().map(RrAwardDtos.AnnualRegisterRow::nomineeDisplayName).distinct().count();if(cohort<minimumCohort)return new RrReportData.Analytics(year,minimumCohort,cohort,true,"Results are suppressed because the distinct nominee cohort is below the configured minimum.",List.of());Map<String,long[]>g=new LinkedHashMap<>();r.records().forEach(x->{var z=g.computeIfAbsent(x.categoryTitle(),k->new long[2]);if("REVOKED".equals(x.status()))z[1]++;else z[0]++;});return new RrReportData.Analytics(year,minimumCohort,cohort,false,null,g.entrySet().stream().map(e->new RrReportData.Metric(e.getKey(),e.getValue()[0],e.getValue()[1])).toList());}
 private static void add(List<RrReportData.Row>r,String s,String l,Object value){r.add(new RrReportData.Row(s,l,v(value)));}private static String v(Object o){return o==null?"—":String.valueOf(o);}
}
